<?php
require __DIR__.'/includes/bootstrap.php';if(empty($_SESSION['user_id'])||empty($_SESSION['cart']))redirect('/cart.php');
$pdo->beginTransaction();try{$ids=array_map('intval',array_keys($_SESSION['cart']));$ph=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT id,price FROM products WHERE active=1 AND id IN ($ph) FOR UPDATE");$s->execute($ids);$ps=$s->fetchAll();$total=0;foreach($ps as $p)$total+=(float)$p['price']*(int)$_SESSION['cart'][$p['id']];$o=$pdo->prepare('INSERT INTO orders(user_id,total,status) VALUES(?,?,?)');$o->execute([$_SESSION['user_id'],$total,'new']);$oid=(int)$pdo->lastInsertId();$i=$pdo->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)');foreach($ps as $p)$i->execute([$oid,$p['id'],(int)$_SESSION['cart'][$p['id']],$p['price']]);$pdo->commit();$_SESSION['cart']=[];redirect('/account.php?ordered=1');}catch(Throwable $e){$pdo->rollBack();http_response_code(500);exit('Unable to create order.');}
